<script setup lang="ts">
import OptionSelect from '@/Components/UI/OptionSelect.vue';
import { DELIVERY_METHODS, HOLD_AUTHORITIES, HOLD_REASONS, LAWFUL_AUTHORITIES, PARTNER_AGENCIES, RECORD_TYPES, SHARING_PURPOSES } from '@/utils/caseOptions';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
const props=defineProps<{caseId:number;classifications:any[];records:any[];holds:any[];disclosures:any[]}>();
const hold=useForm({scope:'case',reason_code:'',authority:'',review_at:'',record_type:'document',record_id:'' as string|number});
const disclosure=useForm({recipient_organization:'',recipient_name:'',purpose:'',lawful_authority:'',delivery_method:'secure_transfer',items:[] as any[]});
const classify=(record:any, classification:string|number)=>useForm({record_classification_id:classification||null,retention_rule_id:null}).patch(route('cases.documents.governance.update',[props.caseId,record.record_id]));
const placeHold=()=>hold.post(route('cases.records.holds.store',props.caseId));
const release=(id:number)=>useForm({release_reason:'Authorized release recorded.'}).patch(route('cases.records.holds.release',[props.caseId,id]));
const propose=(record:any)=>useForm({proposal_reason:'Retention review requires authorized disposition decision.'}).post(route('cases.records.dispositions.store',[props.caseId,record.id]));
const reviewDisposition=(record:any,action:string)=>useForm({action,reason_code:'Authorized governance review'}).patch(route('cases.records.dispositions.review',[props.caseId,record.id]));
const addDisclosure=(record:any)=>{disclosure.items=[{record_type:record.record_type,record_id:record.record_id,category:'approved_record'}]};
const saveDisclosure=()=>disclosure.post(route('cases.records.disclosures.store',props.caseId));
</script>
<template><Head title="Records governance"/><AuthenticatedLayout><section class="records-governance mx-auto max-w-6xl space-y-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-sm font-bold text-brand-700">Case workspace</p><h1 class="mt-1 text-2xl font-extrabold">Records governance</h1><p class="mt-2 max-w-3xl text-sm text-slate-600">Retention review is not destruction. Disposition execution is disabled until an approved policy, authority, and disposal method are configured.</p></div><Link :href="route('cases.show',caseId)" class="min-h-11 rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold">Back to case</Link></div>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950"><strong>Policy validation required.</strong> Classifications and retention rules may support review only until formally approved. Legal holds override all disposition actions.</section>
<section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-bold">Governed records</h2><p class="mt-1 text-sm text-slate-500">Only supported record types are accepted. Similar filenames never create a version relationship.</p><div class="mt-4 space-y-3"><article v-for="record in records" :key="record.id" class="rounded-xl border border-slate-200 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="font-bold capitalize">{{record.record_type}} #{{record.record_id}}</p><p class="mt-1 text-xs text-slate-500">Lifecycle: {{record.lifecycle_state.replaceAll('_',' ')}} · Scan: {{record.scan_state.replaceAll('_',' ')}}<span v-if="record.legacy_record"> · Legacy / unverified</span></p></div><div class="flex flex-wrap gap-2"><button type="button" class="min-h-11 rounded-xl border border-amber-300 px-3 text-sm font-bold text-amber-900" @click="propose(record)">Propose disposition</button><button v-if="record.lifecycle_state==='disposition_pending'" type="button" class="min-h-11 rounded-xl border border-slate-300 px-3 text-sm font-bold" @click="reviewDisposition(record,'reviewed')">Mark reviewed</button><button v-if="record.lifecycle_state==='disposition_pending'" type="button" class="min-h-11 rounded-xl bg-slate-800 px-3 text-sm font-bold text-white" @click="reviewDisposition(record,'approved')">Approve - execution disabled</button></div></div><label class="mt-3 block text-sm font-semibold">Classification<select :value="record.record_classification_id||''" class="mt-1 block w-full rounded-xl border-slate-300" @change="classify(record,($event.target as HTMLSelectElement).value)"><option value="">Not classified</option><option v-for="classification in classifications" :key="classification.id" :value="classification.id">{{classification.label}}{{!classification.policy_validated?' - policy validation required':''}}</option></select></label><button type="button" class="mt-3 text-sm font-bold text-brand-700" @click="addDisclosure(record)">Add to disclosure ledger</button></article><p v-if="!records.length" class="text-sm text-slate-500">No records have been classified yet. Existing documents remain legacy/unverified until reviewed.</p></div></section>
<div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-bold">Legal holds</h2><form class="mt-4 space-y-3" @submit.prevent="placeHold"><label class="block text-sm font-semibold">Scope<select v-model="hold.scope" class="mt-1 block w-full rounded-xl border-slate-300"><option value="case">Entire case and applicable governed records</option><option value="record">One governed record</option></select></label><template v-if="hold.scope==='record'"><label class="block text-sm font-semibold">Record type<OptionSelect v-model="hold.record_type" :options="RECORD_TYPES" :allow-other="false" /></label><label class="block text-sm font-semibold">Record ID<input v-model="hold.record_id" inputmode="numeric" class="mt-1 block w-full rounded-xl border-slate-300"></label></template><label class="block text-sm font-semibold">Reason code<OptionSelect v-model="hold.reason_code" :options="HOLD_REASONS" required /></label><label class="block text-sm font-semibold">Authority<OptionSelect v-model="hold.authority" :options="HOLD_AUTHORITIES" required /></label><label class="block text-sm font-semibold">Review date<input v-model="hold.review_at" type="date" class="mt-1 block w-full rounded-xl border-slate-300"></label><button class="min-h-11 rounded-xl bg-brand-700 px-4 py-2 text-sm font-bold text-white">Place legal hold</button></form><div class="mt-5 space-y-2"><article v-for="item in holds" :key="item.id" class="rounded-xl bg-slate-50 p-3 text-sm"><p class="font-bold">{{item.scope}} hold · {{item.reason_code}}</p><p class="mt-1 text-xs text-slate-500">{{item.authority}} · {{item.placed_at}}</p><button v-if="!item.released_at" type="button" class="mt-2 font-bold text-rose-700" @click="release(item.id)">Release hold</button><p v-else class="mt-1 text-xs font-semibold text-slate-600">Released {{item.released_at}}</p></article></div></section>
<section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-bold">Controlled disclosure ledger</h2><p class="mt-1 text-sm text-slate-500">Records reference exact versions/items. Never enter case narratives here.</p><form class="mt-4 space-y-3" @submit.prevent="saveDisclosure"><label class="block text-sm font-semibold">Recipient organization<OptionSelect v-model="disclosure.recipient_organization" :options="PARTNER_AGENCIES" required /></label><label class="block text-sm font-semibold">Recipient name (optional)<input v-model="disclosure.recipient_name" class="mt-1 block w-full rounded-xl border-slate-300"></label><label class="block text-sm font-semibold">Purpose<OptionSelect v-model="disclosure.purpose" :options="SHARING_PURPOSES" required /></label><label class="block text-sm font-semibold">Lawful authority<OptionSelect v-model="disclosure.lawful_authority" :options="LAWFUL_AUTHORITIES" required /></label><label class="block text-sm font-semibold">Delivery method<OptionSelect v-model="disclosure.delivery_method" :options="DELIVERY_METHODS" required /></label><p class="text-xs text-slate-500">{{disclosure.items.length}} exact record reference(s) selected.</p><button :disabled="!disclosure.items.length" class="min-h-11 rounded-xl bg-brand-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">Record disclosure</button></form><div class="mt-5 space-y-2"><article v-for="item in disclosures" :key="item.id" class="rounded-xl bg-slate-50 p-3 text-sm"><p class="font-bold">{{item.recipient_organization}}</p><p class="mt-1 text-xs text-slate-500">{{item.delivery_method}} · Authorized {{item.authorized_at}}</p></article></div></section></div>
</section></AuthenticatedLayout></template>
<style scoped>
.records-governance :is(button,input,select,textarea) { min-height: 2.75rem; }
.records-governance button:focus-visible, .records-governance input:focus-visible, .records-governance select:focus-visible, .records-governance textarea:focus-visible { outline: 3px solid #c4b5fd; outline-offset: 2px; }
</style>
